world_checks.check_appointments_match_calendar:
def check(world):
    s = world.state()
    events = {e["event_id"]: e for e in s.get("calendar_events", [])}
    staff = {r["staff_id"]: r for r in s.get("staff", [])}
    appts = {a["appointment_id"]: a for a in s.get("appointments", [])}
    if len(appts) < 20 or len(staff) < 6 or len(events) < 20:
        return "the bookings, staff or calendars are missing"
    for a in appts.values():
        e = events.get(a["calendar_event_id"])
        if not e:
            return f"appointment {a['appointment_id']} has no calendar event"
        if e["calendar_id"] != staff[a["staff_id"]]["calendar_id"]:
            return f"appointment {a['appointment_id']}'s event is on {e['calendar_id']}, not its staff calendar"
        if (e["start_time"], e["end_time"]) != (a["start_utc"], a["end_utc"]):
            return f"appointment {a['appointment_id']} and its event disagree on the time"
        want = "confirmed" if a["status"] in ("booked", "completed") else "cancelled"
        if e["status"] != want:
            return f"appointment {a['appointment_id']} is {a['status']} but its event is {e['status']}"
    staff_cals = {r["calendar_id"] for r in staff.values()}
    for e in events.values():
        if e["calendar_id"] not in staff_cals:
            continue
        d = e.get("description") or ""
        if d.startswith("block:"):
            continue
        aid = d.split(":", 1)[1] if d.startswith("appointment:") else None
        if not aid or aid not in appts or appts[aid]["calendar_event_id"] != e["event_id"]:
            return f"event {e['event_id']} on {e['calendar_id']} has no appointment record"
    live = {}
    for e in events.values():
        if e["status"] == "cancelled" or e["calendar_id"] not in staff_cals:
            continue
        for o in live.get(e["calendar_id"], []):
            if o["start_time"] < e["end_time"] and e["start_time"] < o["end_time"]:
                return f"{e['event_id']} and {o['event_id']} overlap on {e['calendar_id']}"
        live.setdefault(e["calendar_id"], []).append(e)
    return None

world_checks.check_links_and_outbox:
def check(world):
    s = world.state()
    customers = {c["customer_id"]: c for c in s.get("customers", [])}
    staff = {r["staff_id"] for r in s.get("staff", [])}
    services = {r["service_id"] for r in s.get("services", [])}
    appts = {a["appointment_id"]: a for a in s.get("appointments", [])}
    if len(customers) < 10 or len(appts) < 20 or len(s.get("gmail_messages", [])) < 14 or not s.get("confirmation_outbox"):
        return "the customers, bookings, mailbox or outbox are missing"
    for a in appts.values():
        if a["customer_id"] not in customers or a["staff_id"] not in staff or a["service_id"] not in services:
            return f"appointment {a['appointment_id']} names an unknown record"
        if a["rescheduled_from"] and appts.get(a["rescheduled_from"], {}).get("status") != "rescheduled":
            return f"{a['appointment_id']} replaces {a['rescheduled_from']}, which is not marked rescheduled"
    for o in s.get("confirmation_outbox", []):
        a = appts.get(o["appointment_id"])
        if not a:
            return f"outbox {o['outbox_id']} confirms an appointment that does not exist"
        if o["kind"] == "cancelled" and a["status"] != "cancelled":
            return f"outbox {o['outbox_id']} confirms a cancellation that did not happen"
        if o["kind"] == "rescheduled" and not a["rescheduled_from"]:
            return f"outbox {o['outbox_id']} confirms a reschedule that did not happen"
    for table in ("holds", "waitlist", "customer_preferences"):
        for r in s.get(table, []):
            if r["customer_id"] not in customers:
                return f"{table} row names unknown customer {r['customer_id']}"
    seen = {}
    for c in customers.values():
        e = c["email"].lower()
        if e in seen:
            return f"{c['customer_id']} and {seen[e]} share the email {e}"
        seen[e] = c["customer_id"]
    for a in appts.values():
        if a["updated_at"] < a["created_at"] or (a["cancelled_at"] and a["cancelled_at"] < a["created_at"]):
            return f"appointment {a['appointment_id']} was changed before it was made"
    desk = {r["desk_id"] for r in s.get("desk_staff", [])}
    for r in s.get("session_caller", []):
        if (r["customer_id"] and r["customer_id"] not in customers) or (r["desk_id"] and r["desk_id"] not in desk):
            return "the session's caller names no customer or desk member on file"
    emails = {c["email"].lower() for c in customers.values()}
    for m in s.get("gmail_messages", []):
        sender = m["sender"].lower()
        if sender.endswith("@example.com") and sender not in emails and sender != "nora.quinn@example.com":
            return f"message {m['id']} comes from {sender}, who is not a customer"
    return None

world_checks.check_parameters_match_policy:
def check(world):
    want = {'slot_interval_minutes': '15', 'booking_min_notice_hours': '2', 'booking_horizon_days': '30', 'late_cancel_window_hours': '24', 'late_cancel_fee_cents': '2500', 'hold_minutes': '15'}
    have = {r["name"]: r["value"] for r in world.state().get("environment_policy", [])}
    for k, v in want.items():
        if have.get(k) != v:
            return f"parameter {k} is {have.get(k)!r}, policy.json says {v}"
    return None
